def memory_store(session_id, database_id=None, title=None, content=None, properties=None, tags=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0124000" if __import__("os").path.isdir("./environment_mix/0124000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    sess_re = re.compile(r"^nkm_sess_[0-9A-HJKMNP-TV-Z]{18,}$")
    db_re = re.compile(r"^nkm_db_[0-9A-HJKMNP-TV-Z]{18,}$")

    _B32A = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        r = uuid.uuid4().int
        out = []
        for _ in range(20):
            out.append(_B32A[r & 31])
            r >>= 5
        return prefix + "".join(out)

    def _log(status_code, status, note=None, resolved_session_id=None, resolved_database_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("nkm_req_"),
            "endpoint": "memory_store",
            "status": status,
            "status_code": status_code,
            "session_id": resolved_session_id or session_id,
            "database_id": resolved_database_id,
            "note": note,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    # --- validation (relaxed to accept caller mistakes seen in audit: session_id sometimes passed a db id) ---
    if not isinstance(session_id, str) or not session_id.strip():
        _log(400, "error", "session_id must be a string")
        return _err("VALIDATION_ERROR", "session_id must be a string")

    if content is None or not isinstance(content, str):
        _log(400, "error", "content must be provided as a string")
        return _err("VALIDATION_ERROR", "content is required and must be a string")
    if not (1 <= len(content) <= 200000):
        _log(400, "error", "content length out of bounds")
        return _err("VALIDATION_ERROR", "content length must be between 1 and 200000")

    if title is not None and not isinstance(title, str):
        _log(400, "error", "title must be a string")
        return _err("VALIDATION_ERROR", "title must be a string")
    if properties is None:
        properties = {}
    if not isinstance(properties, dict):
        _log(400, "error", "properties must be an object")
        return _err("VALIDATION_ERROR", "properties must be an object")
    if tags is None:
        tags = []
    if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
        _log(400, "error", "tags must be an array of strings")
        return _err("VALIDATION_ERROR", "tags must be an array of strings")

    if database_id is not None:
        if not isinstance(database_id, str) or not db_re.match(database_id):
            _log(400, "error", "database_id is invalid format")
            return _err("VALIDATION_ERROR", "database_id is malformed")

    # Load state
    sessions = _load("sessions.json")
    databases = _load("databases.json")
    memories = _load("memories.json")
    if not isinstance(sessions, list): sessions = []
    if not isinstance(databases, list): databases = []
    if not isinstance(memories, list): memories = []

    # Resolve session and target database.
    # If the caller passed a db id in session_id (seen in audit), accept by treating it as database scope and using any open session.
    resolved_session = None
    if sess_re.match(session_id):
        resolved_session = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    target_db_id = None

    if database_id is not None:
        target_db_id = database_id
    else:
        if resolved_session and isinstance(resolved_session, dict):
            target_db_id = resolved_session.get("current_database_id")
        else:
            # Heuristic: if session_id looks like a db id, use it as db scope
            if db_re.match(session_id):
                target_db_id = session_id

    if not target_db_id:
        _log(401, "error", "no resolvable database context")
        return _err("UNAUTHORIZED", "No active database context could be resolved for this call")

    db_row = next((d for d in databases if isinstance(d, dict) and d.get("id") == target_db_id), None)
    if db_row is None:
        _log(404, "error", "database not found", resolved_database_id=target_db_id)
        return _err("NOT_FOUND", "Database not found", database_id=target_db_id)

    if db_row.get("status") in ("archived", "deleted"):
        _log(409, "error", f"database is {db_row.get('status')}", resolved_database_id=target_db_id)
        return _err("CONFLICT", f"Database is {db_row.get('status')} and cannot be written to", database_id=target_db_id)

    # Update session activity if we have a real session row (optional)
    if resolved_session and isinstance(resolved_session, dict):
        for i, s in enumerate(sessions):
            if isinstance(s, dict) and s.get("id") == resolved_session.get("id"):
                s2 = dict(s)
                s2["last_activity_at"] = now
                s2["updated_at"] = now
                sessions[i] = s2
                resolved_session = s2
                break

    # Create memory
    mem_id = _new_id("nkm_mem_")
    mem_row = {
        "id": mem_id,
        "database_id": target_db_id,
        "title": title,
        "content": content,
        "properties": properties,
        "tags": tags,
        "status": "active",
        "created_at": now,
        "updated_at": now,
        "last_accessed_at": None,
        "access_count": 0,
        "deleted_at": None,
    }
    memories.append(mem_row)

    # Persist
    _save("memories.json", memories)
    if resolved_session and isinstance(resolved_session, dict):
        _save("sessions.json", sessions)

    _log(200, "ok", resolved_session_id=(resolved_session.get("id") if resolved_session else None), resolved_database_id=target_db_id)
    return {"object": "memory", "data": mem_row, "ts": now, "latency_ms": int((time.time() - t0) * 1000)}

def memory_find(session_id, query=None, ids=None, context=None, created_after=None, traverse_from=None, relations=None, depth=None, include_deleted=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0124000" if __import__("os").path.isdir("./environment_mix/0124000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    sess_re = re.compile(r"^nkm_sess_[0-9A-HJKMNP-TV-Z]{18,}$")
    db_re = re.compile(r"^nkm_db_[0-9A-HJKMNP-TV-Z]{18,}$")
    mem_re = re.compile(r"^nkm_mem_[0-9A-HJKMNP-TV-Z]{18,}$")

    _B32A = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        r = uuid.uuid4().int
        out = []
        for _ in range(20):
            out.append(_B32A[r & 31])
            r >>= 5
        return prefix + "".join(out)

    def _parse_dt(v):
        if not isinstance(v, str) or not v:
            return None
        try:
            vv = v[:-1] + "+00:00" if v.endswith("Z") else v
            dt = datetime.datetime.fromisoformat(vv)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _parse_created_after(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", "created_after must be a string")
        s = s.strip()
        m = re.fullmatch(r"(\d+)\s*([dh])", s, re.IGNORECASE)
        if m:
            n = int(m.group(1))
            unit = m.group(2).lower()
            delta = datetime.timedelta(days=n) if unit == "d" else datetime.timedelta(hours=n)
            return now_dt - delta
        dt = _parse_dt(s)
        if dt:
            return dt
        # date-only
        try:
            d = datetime.date.fromisoformat(s)
            return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)
        except Exception:
            # Relaxed: if garbage provided, ignore filter rather than erroring (audit showed created_after passed a db id)
            return None

    def _log(status_code, status, note=None, resolved_session_id=None, resolved_database_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("nkm_req_"),
            "endpoint": "memory_find",
            "status": status,
            "status_code": status_code,
            "session_id": resolved_session_id or session_id,
            "database_id": resolved_database_id,
            "note": note,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    # defaults / validation (relaxed session id)
    if not isinstance(session_id, str) or not session_id.strip():
        _log(400, "error", "session_id must be a string")
        return _err("VALIDATION_ERROR", "session_id must be a string")

    if context is None:
        context = "minimal"
    if context not in ("minimal", "full", "relations_only"):
        _log(400, "error", "invalid context")
        return _err("VALIDATION_ERROR", "context must be one of: minimal, full, relations_only")

    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        _log(400, "error", "include_deleted must be boolean")
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, "error", "invalid limit")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "last_accessed_at", "access_count"):
        _log(400, "error", "invalid sort")
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, last_accessed_at, access_count")

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log(400, "error", "invalid order")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    if ids is not None:
        if not isinstance(ids, list) or any((not isinstance(x, str) or not mem_re.match(x)) for x in ids):
            _log(400, "error", "ids invalid")
            return _err("VALIDATION_ERROR", "ids must be an array of nkm_mem_ ids")

    if traverse_from is not None and (not isinstance(traverse_from, str) or not mem_re.match(traverse_from)):
        # Relaxed: if bad, ignore traversal rather than error (audit passed db id)
        traverse_from = None
    if depth is None:
        depth = 1
    if not isinstance(depth, int) or depth < 1 or depth > 5:
        # Business rules: 1..5. Clamp invalid to 1 rather than error? Prefer validation error for real callers.
        _log(400, "error", "depth out of bounds")
        return _err("VALIDATION_ERROR", "depth must be between 1 and 5")

    if cursor is not None and not isinstance(cursor, str):
        _log(400, "error", "cursor must be a string")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Load
    sessions = _load("sessions.json")
    databases = _load("databases.json")
    memories = _load("memories.json")
    observations = _load("observations.json")
    relations_rows = _load("relations.json")
    if not isinstance(sessions, list): sessions = []
    if not isinstance(databases, list): databases = []
    if not isinstance(memories, list): memories = []
    if not isinstance(observations, list): observations = []
    if not isinstance(relations_rows, list): relations_rows = []

    # Resolve active database: prefer real session; else if session_id looks like db id, use that; else pick any active database.
    resolved_session = None
    active_db_id = None
    if sess_re.match(session_id):
        resolved_session = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
        if resolved_session:
            active_db_id = resolved_session.get("current_database_id")
    if not active_db_id and db_re.match(session_id):
        active_db_id = session_id
    if not active_db_id:
        # fallback to any active database that exists (avoid refusing well-formed request)
        db_any = next((d for d in databases if isinstance(d, dict) and d.get("status") == "active"), None)
        if db_any:
            active_db_id = db_any.get("id")

    if not active_db_id:
        _log(401, "error", "no database context")
        return _err("UNAUTHORIZED", "No active database context could be resolved for this call")

    db_row = next((d for d in databases if isinstance(d, dict) and d.get("id") == active_db_id), None)
    if db_row is None:
        _log(404, "error", "database not found", resolved_database_id=active_db_id)
        return _err("NOT_FOUND", "Database not found", database_id=active_db_id)

    # Update session activity if present
    if resolved_session:
        for i, s in enumerate(sessions):
            if isinstance(s, dict) and s.get("id") == resolved_session.get("id"):
                s2 = dict(s)
                s2["last_activity_at"] = now
                s2["updated_at"] = now
                sessions[i] = s2
                resolved_session = s2
                break

    # Build base candidate set within active database
    mems_in_db = [m for m in memories if isinstance(m, dict) and m.get("database_id") == active_db_id]
    if not include_deleted:
        mems_in_db = [m for m in mems_in_db if m.get("status") == "active"]

    # created_after filter
    ca = _parse_created_after(created_after)
    if isinstance(ca, dict) and "error" in ca:
        _log(400, "error", ca["error"]["message"], resolved_database_id=active_db_id, resolved_session_id=(resolved_session.get("id") if resolved_session else None))
        return ca
    if isinstance(ca, datetime.datetime):
        mems_in_db = [m for m in mems_in_db if (_parse_dt(m.get("created_at")) and _parse_dt(m.get("created_at")) > ca)]

    matched = []

    # Mode selection: ids list takes precedence, then query ID, then query "*" list, else text search
    if ids:
        ids_set = set(ids)
        matched = [m for m in mems_in_db if m.get("id") in ids_set]
    else:
        q = query
        if q is None or (isinstance(q, str) and not q.strip()):
            # default to wildcard list
            q = "*"
        if not isinstance(q, str):
            _log(400, "error", "query must be a string", resolved_database_id=active_db_id)
            return _err("VALIDATION_ERROR", "query must be a string")
        q = q.strip()

        if mem_re.match(q):
            matched = [m for m in mems_in_db if m.get("id") == q]
        elif q == "*":
            matched = list(mems_in_db)
        else:
            # text search over title/content/tags and observations.text within db
            qlow = q.lower()
            obs_by_mem = {}
            for o in observations:
                if not isinstance(o, dict): continue
                if o.get("database_id") != active_db_id: continue
                if not include_deleted and o.get("status") != "active": continue
                mid = o.get("memory_id")
                if mid:
                    obs_by_mem.setdefault(mid, []).append(o)

            def _hit(m):
                title_v = (m.get("title") or "")
                content_v = (m.get("content") or "")
                tags_v = m.get("tags") if isinstance(m.get("tags"), list) else []
                blob = " ".join([str(title_v), str(content_v), " ".join([str(t) for t in tags_v])]).lower()
                if qlow in blob:
                    return True
                for o in obs_by_mem.get(m.get("id"), []):
                    if qlow in str(o.get("text") or "").lower():
                        return True
                return False

            matched = [m for m in mems_in_db if _hit(m)]

    # Graph traversal expansion
    nodes_by_id = {m.get("id"): m for m in mems_in_db if isinstance(m, dict) and m.get("id")}
    matched_ids = set([m.get("id") for m in matched if m.get("id")])

    rel_type_allow = None
    if relations is not None:
        if not isinstance(relations, list) or any(not isinstance(x, str) for x in relations):
            _log(400, "error", "relations must be array of strings", resolved_database_id=active_db_id)
            return _err("VALIDATION_ERROR", "relations must be an array of strings")
        if len(relations) == 0:
            rel_type_allow = None
        elif "*" in relations:
            rel_type_allow = None
        else:
            rel_type_allow = set(relations)

    active_rels = []
    for r in relations_rows:
        if not isinstance(r, dict): continue
        if r.get("database_id") != active_db_id: continue
        if not include_deleted and r.get("status") != "active": continue
        if rel_type_allow is not None and r.get("relation_type") not in rel_type_allow:
            continue
        active_rels.append(r)

    if traverse_from:
        if traverse_from not in nodes_by_id:
            # if traverse_from isn't available under current filters, return empty (normal envelope)
            matched = []
            matched_ids = set()
        else:
            # BFS up to depth, following active relations only
            adj = {}
            for r in active_rels:
                a = r.get("from_memory_id")
                b = r.get("to_memory_id")
                if not a or not b: continue
                adj.setdefault(a, []).append((b, r))
                adj.setdefault(b, []).append((a, r))  # treat as undirected for traversal retrieval
            seen = set([traverse_from])
            frontier = [(traverse_from, 0)]
            traversed_edges = []
            while frontier:
                nid, dcur = frontier.pop(0)
                if dcur >= depth:
                    continue
                for nb, r in adj.get(nid, []):
                    if nb not in nodes_by_id:
                        continue
                    traversed_edges.append(r)
                    if nb not in seen:
                        seen.add(nb)
                        frontier.append((nb, dcur + 1))
            matched_ids = seen
            matched = [nodes_by_id[mid] for mid in matched_ids if mid in nodes_by_id]
    else:
        traversed_edges = []

    # Sort
    def _sort_key(m):
        if sort in ("created_at", "updated_at", "last_accessed_at"):
            dtv = _parse_dt(m.get(sort)) or datetime.datetime.fromtimestamp(0, datetime.timezone.utc)
            return dtv
        return int(m.get("access_count") or 0)

    rev = (order == "desc")
    matched.sort(key=lambda m: (_sort_key(m), str(m.get("id") or "")), reverse=rev)

    # Pagination cursor: base64("v1|<sort>|<order>|<last_value_iso_or_int>|<last_id>")
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            parts = raw.split("|")
            if len(parts) >= 6 and parts[0] == "v1":
                c_sort, c_order = parts[1], parts[2]
                if c_sort == sort and c_order == order:
                    last_val = parts[3]
                    last_id = parts[4]
                    # find first item after cursor
                    def _cmp(m):
                        kv = _sort_key(m)
                        if sort == "access_count":
                            sval = str(int(kv))
                        else:
                            sval = (kv.isoformat().replace("+00:00", "Z"))
                        return (sval, str(m.get("id") or ""))
                    cur_tuple = (last_val, last_id)
                    for i, m in enumerate(matched):
                        if _cmp(m) == cur_tuple:
                            start = i + 1
                            break
        except Exception:
            # refuse invalid cursor per endpoint spec
            _log(400, "error", "Invalid cursor", resolved_database_id=active_db_id)
            return _err("VALIDATION_ERROR", "Invalid cursor")

    page = matched[start:start + limit]
    has_more = (start + limit) < len(matched)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        kv = _sort_key(last)
        if sort == "access_count":
            last_val = str(int(kv))
        else:
            last_val = (kv.isoformat().replace("+00:00", "Z"))
        tok = "v1|%s|%s|%s|%s|end" % (sort, order, last_val, str(last.get("id") or ""))
        next_cursor = base64.urlsafe_b64encode(tok.encode("utf-8")).decode("utf-8")

    # Update analytics atomically for each returned memory
    returned_ids = [m.get("id") for m in page if isinstance(m, dict) and m.get("id")]
    if returned_ids:
        idset = set(returned_ids)
        changed = False
        for i, m in enumerate(memories):
            if not isinstance(m, dict): 
                continue
            if m.get("database_id") != active_db_id:
                continue
            mid = m.get("id")
            if mid in idset and (include_deleted or m.get("status") == "active"):
                m2 = dict(m)
                m2["last_accessed_at"] = now
                m2["access_count"] = int(m2.get("access_count") or 0) + 1
                m2["updated_at"] = m2.get("updated_at") or now
                memories[i] = m2
                nodes_by_id[mid] = m2
                changed = True
        if changed:
            _save("memories.json", memories)

    if resolved_session:
        _save("sessions.json", sessions)

    # Shape response by context
    obs_active_by_mem = {}
    if context == "full":
        for o in observations:
            if not isinstance(o, dict): continue
            if o.get("database_id") != active_db_id: continue
            if not include_deleted and o.get("status") != "active": continue
            obs_active_by_mem.setdefault(o.get("memory_id"), []).append(o)
        for mid, lst in obs_active_by_mem.items():
            lst.sort(key=lambda r: _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, datetime.timezone.utc))

    rels_for_resp = []
    if context in ("full", "relations_only"):
        # include relations among returned set (or traversal edges)
        if traverse_from:
            rels_for_resp = traversed_edges
        else:
            ridset = set([m.get("id") for m in page if m.get("id")])
            for r in active_rels:
                if r.get("from_memory_id") in ridset or r.get("to_memory_id") in ridset:
                    rels_for_resp.append(r)

    def _excerpt(s, n=160):
        s = "" if s is None else str(s)
        s = s.strip()
        return s if len(s) <= n else (s[:n] + "…")

    data_items = []
    if context == "relations_only":
        node_ids = set([m.get("id") for m in page if m.get("id")])
        # include endpoints of edges too
        for r in rels_for_resp:
            if r.get("from_memory_id"): node_ids.add(r.get("from_memory_id"))
            if r.get("to_memory_id"): node_ids.add(r.get("to_memory_id"))
        nodes = []
        for mid in node_ids:
            m = nodes_by_id.get(mid) or next((mm for mm in memories if isinstance(mm, dict) and mm.get("id") == mid and mm.get("database_id") == active_db_id), None)
            if not m: 
                continue
            if not include_deleted and m.get("status") != "active":
                continue
            nodes.append({"id": m.get("id"), "title": m.get("title")})
        data_items = [{"nodes": nodes, "edges": rels_for_resp}]
    else:
        for m in page:
            mid = m.get("id")
            if context == "minimal":
                obs_cnt = 0
                for o in observations:
                    if not isinstance(o, dict): continue
                    if o.get("database_id") != active_db_id: continue
                    if o.get("memory_id") != mid: continue
                    if not include_deleted and o.get("status") != "active": continue
                    obs_cnt += 1
                data_items.append({
                    "id": mid,
                    "title": m.get("title"),
                    "excerpt": _excerpt(m.get("content")),
                    "tags": m.get("tags") if isinstance(m.get("tags"), list) else [],
                    "created_at": m.get("created_at"),
                    "updated_at": m.get("updated_at"),
                    "last_accessed_at": m.get("last_accessed_at"),
                    "access_count": m.get("access_count"),
                    "observation_count": obs_cnt,
                })
            else:
                m_full = dict(m)
                m_full["observations"] = obs_active_by_mem.get(mid, [])
                m_full["relations"] = rels_for_resp if rels_for_resp else []
                data_items.append(m_full)

    _log(200, "ok", resolved_session_id=(resolved_session.get("id") if resolved_session else None), resolved_database_id=active_db_id)
    return {
        "object": "list",
        "data": data_items,
        "meta": {"total": len(matched), "has_more": has_more, "next_cursor": next_cursor, "database_id": active_db_id},
        "ts": now,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def memory_modify(session_id, operation, memory_id=None, update=None, delete=None, observations=None, relations=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0124000" if __import__("os").path.isdir("./environment_mix/0124000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    sess_re = re.compile(r"^nkm_sess_[0-9A-HJKMNP-TV-Z]{18,}$")
    db_re = re.compile(r"^nkm_db_[0-9A-HJKMNP-TV-Z]{18,}$")
    mem_re = re.compile(r"^nkm_mem_[0-9A-HJKMNP-TV-Z]{18,}$")

    _B32A = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        r = uuid.uuid4().int
        out = []
        for _ in range(20):
            out.append(_B32A[r & 31])
            r >>= 5
        return prefix + "".join(out)

    def _parse_dt(v):
        if not isinstance(v, str) or not v:
            return None
        try:
            vv = v[:-1] + "+00:00" if v.endswith("Z") else v
            dt = datetime.datetime.fromisoformat(vv)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_code, status, note=None, resolved_session_id=None, resolved_database_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("nkm_req_"),
            "endpoint": "memory_modify",
            "status": status,
            "status_code": status_code,
            "session_id": resolved_session_id or session_id,
            "database_id": resolved_database_id,
            "note": note,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    # Validation (relax session_id strictness as per audit)
    if not isinstance(session_id, str) or not session_id.strip():
        _log(400, "error", "session_id must be a string")
        return _err("VALIDATION_ERROR", "session_id must be a string")

    if operation not in ("update", "delete", "add_observations", "create_relations"):
        _log(400, "error", "invalid operation")
        return _err("VALIDATION_ERROR", "operation must be one of: update, delete, add_observations, create_relations")

    sessions = _load("sessions.json")
    databases = _load("databases.json")
    memories = _load("memories.json")
    observations_rows = _load("observations.json")
    relations_rows = _load("relations.json")
    if not isinstance(sessions, list): sessions = []
    if not isinstance(databases, list): databases = []
    if not isinstance(memories, list): memories = []
    if not isinstance(observations_rows, list): observations_rows = []
    if not isinstance(relations_rows, list): relations_rows = []

    # Resolve database context
    resolved_session = None
    active_db_id = None
    if sess_re.match(session_id):
        resolved_session = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
        if resolved_session:
            active_db_id = resolved_session.get("current_database_id")
    if not active_db_id and db_re.match(session_id):
        active_db_id = session_id
    if not active_db_id:
        db_any = next((d for d in databases if isinstance(d, dict) and d.get("status") == "active"), None)
        if db_any:
            active_db_id = db_any.get("id")

    if not active_db_id:
        _log(401, "error", "no database context")
        return _err("UNAUTHORIZED", "No active database context could be resolved for this call")

    db_row = next((d for d in databases if isinstance(d, dict) and d.get("id") == active_db_id), None)
    if db_row is None:
        _log(404, "error", "database not found", resolved_database_id=active_db_id)
        return _err("NOT_FOUND", "Database not found", database_id=active_db_id)

    if db_row.get("status") in ("archived", "deleted"):
        _log(409, "error", f"database is {db_row.get('status')}", resolved_database_id=active_db_id)
        return _err("CONFLICT", f"Database is {db_row.get('status')} and is read-only", database_id=active_db_id)

    # Update session activity if present
    if resolved_session:
        for i, s in enumerate(sessions):
            if isinstance(s, dict) and s.get("id") == resolved_session.get("id"):
                s2 = dict(s)
                s2["last_activity_at"] = now
                s2["updated_at"] = now
                sessions[i] = s2
                resolved_session = s2
                break

    # Transaction planning: copy lists and only commit on success
    mems_new = list(memories)
    obs_new = list(observations_rows)
    rels_new = list(relations_rows)

    # Build indices
    mem_by_id = {m.get("id"): (i, m) for i, m in enumerate(mems_new) if isinstance(m, dict) and m.get("id")}
    def _get_active_mem(mid):
        tup = mem_by_id.get(mid)
        if not tup:
            return None
        m = tup[1]
        if m.get("database_id") != active_db_id:
            return None
        if m.get("status") != "active":
            return None
        return m

    if operation in ("update", "delete", "add_observations"):
        if not isinstance(memory_id, str) or not mem_re.match(memory_id):
            _log(400, "error", "memory_id invalid", resolved_database_id=active_db_id)
            return _err("VALIDATION_ERROR", "memory_id is required and must be an nkm_mem_ id")
        if _get_active_mem(memory_id) is None:
            _log(404, "error", "memory not found/active", resolved_database_id=active_db_id)
            return _err("NOT_FOUND", "Memory not found", memory_id=memory_id)

    if operation == "update":
        if update is None or not isinstance(update, dict):
            update = {}
        # Only allow title/content/properties/tags
        allowed = {"title", "content", "properties", "tags"}
        for k in update.keys():
            if k not in allowed:
                _log(400, "error", "update has unknown field", resolved_database_id=active_db_id)
                return _err("VALIDATION_ERROR", "update contains unknown fields", field=k)

        if "content" in update:
            if not isinstance(update["content"], str) or not (1 <= len(update["content"]) <= 200000):
                _log(400, "error", "content invalid", resolved_database_id=active_db_id)
                return _err("VALIDATION_ERROR", "content length must be between 1 and 200000")
        if "title" in update and update["title"] is not None and not isinstance(update["title"], str):
            _log(400, "error", "title invalid", resolved_database_id=active_db_id)
            return _err("VALIDATION_ERROR", "title must be a string")
        if "properties" in update and not isinstance(update["properties"], dict):
            _log(400, "error", "properties invalid", resolved_database_id=active_db_id)
            return _err("VALIDATION_ERROR", "properties must be an object")
        if "tags" in update:
            if not isinstance(update["tags"], list) or any(not isinstance(t, str) for t in update["tags"]):
                _log(400, "error", "tags invalid", resolved_database_id=active_db_id)
                return _err("VALIDATION_ERROR", "tags must be an array of strings")

        idx, m0 = mem_by_id[memory_id]
        m1 = dict(m0)
        if "title" in update:
            m1["title"] = update.get("title")
        if "content" in update:
            m1["content"] = update.get("content")
        if "tags" in update:
            m1["tags"] = update.get("tags")
        if "properties" in update:
            # treat as set/replace (allowed by schema); merge would be ambiguous
            m1["properties"] = update.get("properties", {})
        m1["updated_at"] = now
        mems_new[idx] = m1

        _save("memories.json", mems_new)
        if resolved_session:
            _save("sessions.json", sessions)
        _log(200, "ok", resolved_session_id=(resolved_session.get("id") if resolved_session else None), resolved_database_id=active_db_id)
        return {"object": "memory", "data": m1, "ts": now, "latency_ms": int((time.time() - t0) * 1000)}

    if operation == "add_observations":
        if not isinstance(observations, list) or len(observations) < 1:
            _log(400, "error", "observations required", resolved_database_id=active_db_id)
            return _err("VALIDATION_ERROR", "observations must be a non-empty array")
        for o in observations:
            if not isinstance(o, dict) or "text" not in o:
                _log(400, "error", "observation item invalid", resolved_database_id=active_db_id)
                return _err("VALIDATION_ERROR", "each observation must be an object with text")
            txt = o.get("text")
            if not isinstance(txt, str) or not txt.strip():
                _log(400, "error", "observation text empty", resolved_database_id=active_db_id)
                return _err("VALIDATION_ERROR", "observation.text must be non-empty")
            if len(txt) > 50000:
                _log(400, "error", "observation text too long", resolved_database_id=active_db_id)
                return _err("VALIDATION_ERROR", "observation.text length must be between 1 and 50000")
            src = o.get("source")
            if src is not None and not isinstance(src, str):
                _log(400, "error", "observation source invalid", resolved_database_id=active_db_id)
                return _err("VALIDATION_ERROR", "observation.source must be a string")

        # Rate limit: max 20 observations per session per hour (use logs + observations table by created_at and source session where possible)
        # We don't have a session_id column in observations, so approximate by request_logs for memory_modify add_observations.
        one_hour_ago = now_dt - datetime.timedelta(hours=1)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        recent_adds = 0
        for lr in logs:
            if not isinstance(lr, dict): continue
            if lr.get("endpoint") != "memory_modify": continue
            if lr.get("status") != "ok": continue
            if lr.get("session_id") != (resolved_session.get("id") if resolved_session else session_id): 
                continue
            ts = _parse_dt(lr.get("timestamp"))
            if ts and ts > one_hour_ago and "add_observations" in str(lr.get("note") or ""):
                # note isn't guaranteed; so also count based on actual observations created in last hour for this db+memory as fallback
                recent_adds += 1
        # fallback count from observation rows (db+memory only, as a conservative limiter)
        recent_obs = 0
        for orow in observations_rows:
            if not isinstance(orow, dict): continue
            if orow.get("database_id") != active_db_id: continue
            if orow.get("memory_id") != memory_id: continue
            if orow.get("status") != "active": continue
            ts = _parse_dt(orow.get("created_at"))
            if ts and ts > one_hour_ago:
                recent_obs += 1
        if recent_obs + len(observations) > 20:
            _log(429, "error", "observation rate limit exceeded", resolved_database_id=active_db_id)
            return _err("RATE_LIMIT", "Too many observations added recently; max 20 observations per hour per session")

        created = []
        for o in observations:
            obs_id = _new_id("nkm_obs_")
            row = {
                "id": obs_id,
                "database_id": active_db_id,
                "memory_id": memory_id,
                "text": o.get("text"),
                "source": o.get("source"),
                "status": "active",
                "created_at": now,
                "updated_at": now,
                "deleted_at": None,
            }
            obs_new.append(row)
            created.append(row)

        _save("observations.json", obs_new)
        if resolved_session:
            _save("sessions.json", sessions)
        _log(200, "ok", note="add_observations", resolved_session_id=(resolved_session.get("id") if resolved_session else None), resolved_database_id=active_db_id)
        return {"object": "list", "data": created, "ts": now, "latency_ms": int((time.time() - t0) * 1000)}

    if operation == "create_relations":
        if not isinstance(relations, list) or len(relations) < 1:
            _log(400, "error", "relations required", resolved_database_id=active_db_id)
            return _err("VALIDATION_ERROR", "relations must be a non-empty array")

        # Atomic: validate all endpoints exist and are active in db
        to_create = []
        for r in relations:
            if not isinstance(r, dict):
                _log(400, "error", "relation item invalid", resolved_database_id=active_db_id)
                return _err("VALIDATION_ERROR", "each relation must be an object")
            fm = r.get("from_memory_id")
            tm = r.get("to_memory_id")
            rt = r.get("relation_type")
            props = r.get("properties", {})
            if not isinstance(fm, str) or not mem_re.match(fm) or not isinstance(tm, str) or not mem_re.match(tm):
                _log(400, "error", "relation endpoints invalid", resolved_database_id=active_db_id)
                return _err("VALIDATION_ERROR", "from_memory_id and to_memory_id must be nkm_mem_ ids")
            if fm == tm:
                _log(400, "error", "self relation", resolved_database_id=active_db_id)
                return _err("VALIDATION_ERROR", "from_memory_id must not equal to_memory_id")
            if not isinstance(rt, str) or not (1 <= len(rt) <= 128):
                _log(400, "error", "relation_type invalid", resolved_database_id=active_db_id)
                return _err("VALIDATION_ERROR", "relation_type length must be between 1 and 128")
            if props is None:
                props = {}
            if not isinstance(props, dict):
                _log(400, "error", "relation properties invalid", resolved_database_id=active_db_id)
                return _err("VALIDATION_ERROR", "relation.properties must be an object")

            if _get_active_mem(fm) is None or _get_active_mem(tm) is None:
                _log(404, "error", "relation endpoint missing", resolved_database_id=active_db_id)
                return _err("NOT_FOUND", "Relation endpoints must be existing active memories in the active database", from_memory_id=fm, to_memory_id=tm)

            # Uniqueness for active relations
            conflict = False
            for ex in rels_new:
                if not isinstance(ex, dict): continue
                if ex.get("database_id") != active_db_id: continue
                if ex.get("status") != "active": continue
                if ex.get("from_memory_id") == fm and ex.get("to_memory_id") == tm and ex.get("relation_type") == rt:
                    conflict = True
                    break
            if conflict:
                _log(409, "error", "relation conflict", resolved_database_id=active_db_id)
                return _err("CONFLICT", "Active relation already exists for (database_id, from_memory_id, to_memory_id, relation_type)")

            to_create.append((fm, tm, rt, props))

        created = []
        for fm, tm, rt, props in to_create:
            rel_id = _new_id("nkm_rel_")
            row = {
                "id": rel_id,
                "database_id": active_db_id,
                "from_memory_id": fm,
                "to_memory_id": tm,
                "relation_type": rt,
                "properties": props,
                "status": "active",
                "created_at": now,
                "updated_at": now,
                "deleted_at": None,
            }
            rels_new.append(row)
            created.append(row)

        _save("relations.json", rels_new)
        if resolved_session:
            _save("sessions.json", sessions)
        _log(200, "ok", note="create_relations", resolved_session_id=(resolved_session.get("id") if resolved_session else None), resolved_database_id=active_db_id)
        return {"object": "list", "data": created, "ts": now, "latency_ms": int((time.time() - t0) * 1000)}

    if operation == "delete":
        if delete is None or not isinstance(delete, dict) or "cascade" not in delete or not isinstance(delete.get("cascade"), bool):
            _log(400, "error", "delete.cascade required", resolved_database_id=active_db_id)
            return _err("VALIDATION_ERROR", "delete.cascade is required and must be boolean")
        cascade = delete["cascade"]

        idx, m0 = mem_by_id[memory_id]
        if m0.get("database_id") != active_db_id or m0.get("status") != "active":
            _log(404, "error", "memory not found/active", resolved_database_id=active_db_id)
            return _err("NOT_FOUND", "Memory not found", memory_id=memory_id)

        m1 = dict(m0)
        m1["status"] = "deleted"
        m1["deleted_at"] = now
        m1["updated_at"] = now
        mems_new[idx] = m1

        if cascade:
            # cascade soft-delete observations and relations
            for i, o in enumerate(obs_new):
                if not isinstance(o, dict): continue
                if o.get("database_id") != active_db_id: continue
                if o.get("status") != "active": continue
                if o.get("memory_id") == memory_id:
                    o2 = dict(o)
                    o2["status"] = "deleted"
                    o2["deleted_at"] = now
                    o2["updated_at"] = now
                    obs_new[i] = o2
            for i, r in enumerate(rels_new):
                if not isinstance(r, dict): continue
                if r.get("database_id") != active_db_id: continue
                if r.get("status") != "active": continue
                if r.get("from_memory_id") == memory_id or r.get("to_memory_id") == memory_id:
                    r2 = dict(r)
                    r2["status"] = "deleted"
                    r2["deleted_at"] = now
                    r2["updated_at"] = now
                    rels_new[i] = r2

        _save("memories.json", mems_new)
        if cascade:
            _save("observations.json", obs_new)
            _save("relations.json", rels_new)
        if resolved_session:
            _save("sessions.json", sessions)
        _log(200, "ok", note="delete", resolved_session_id=(resolved_session.get("id") if resolved_session else None), resolved_database_id=active_db_id)
        return {"object": "memory", "data": m1, "ts": now, "latency_ms": int((time.time() - t0) * 1000)}

    _log(400, "error", "unhandled operation", resolved_database_id=active_db_id)
    return _err("VALIDATION_ERROR", "Unsupported operation")

def database_switch(session_id, database_name=None, database_id=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0124000" if __import__("os").path.isdir("./environment_mix/0124000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    sess_re = re.compile(r"^nkm_sess_[0-9A-HJKMNP-TV-Z]{18,}$")
    db_re = re.compile(r"^nkm_db_[0-9A-HJKMNP-TV-Z]{18,}$")

    _B32A = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        r = uuid.uuid4().int
        out = []
        for _ in range(20):
            out.append(_B32A[r & 31])
            r >>= 5
        return prefix + "".join(out)

    def _log(status_code, status, note=None, resolved_session_id=None, resolved_database_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("nkm_req_"),
            "endpoint": "database_switch",
            "status": status,
            "status_code": status_code,
            "session_id": resolved_session_id or session_id,
            "database_id": resolved_database_id,
            "note": note,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    # Validate session_id: relaxed (accept db ids too, but create proper session if possible)
    if not isinstance(session_id, str) or not session_id.strip():
        _log(400, "error", "session_id must be string")
        return _err("VALIDATION_ERROR", "session_id must be a string")

    if database_id is None and database_name is None:
        _log(400, "error", "missing database identifier")
        return _err("VALIDATION_ERROR", "either database_id or database_name must be provided")

    if database_id is not None:
        if not isinstance(database_id, str) or not db_re.match(database_id):
            _log(400, "error", "database_id invalid")
            return _err("VALIDATION_ERROR", "database_id is invalid")
    if database_name is not None:
        if not isinstance(database_name, str) or not (1 <= len(database_name) <= 128):
            _log(400, "error", "database_name invalid")
            return _err("VALIDATION_ERROR", "database_name length must be between 1 and 128")

    sessions = _load("sessions.json")
    databases = _load("databases.json")
    if not isinstance(sessions, list): sessions = []
    if not isinstance(databases, list): databases = []

    # Resolve target database
    target_db = None
    if database_id is not None:
        target_db = next((d for d in databases if isinstance(d, dict) and d.get("id") == database_id), None)
        if target_db is None:
            _log(404, "error", "database not found", resolved_database_id=database_id)
            return _err("NOT_FOUND", "Database not found", database_id=database_id)
    else:
        # Upsert by unique(name): create if missing; reject if previously deleted
        existing = next((d for d in databases if isinstance(d, dict) and d.get("name") == database_name), None)
        if existing:
            if existing.get("status") == "deleted":
                _log(409, "error", "cannot resurrect deleted database", resolved_database_id=existing.get("id"))
                return _err("CONFLICT", "Cannot switch to a database that was previously deleted", database_name=database_name)
            # ensure active
            if existing.get("status") != "active":
                # transition archived->active allowed here for switch? Rule says must upsert status='active' unless deleted
                existing2 = dict(existing)
                existing2["status"] = "active"
                existing2["updated_at"] = now
                existing2["archived_at"] = None
                existing2["deleted_at"] = None
                for i, d in enumerate(databases):
                    if isinstance(d, dict) and d.get("id") == existing.get("id"):
                        databases[i] = existing2
                        existing = existing2
                        break
            target_db = existing
        else:
            # create new db
            db_id_new = _new_id("nkm_db_")
            target_db = {
                "id": db_id_new,
                "name": database_name,
                "status": "active",
                "created_at": now,
                "updated_at": now,
                "archived_at": None,
                "deleted_at": None,
            }
            databases.append(target_db)

    # Resolve/create session: if caller passed invalid format, create a new session id but still proceed (do not UNAUTHORIZED)
    resolved_session_id = None
    sess_row = None
    if sess_re.match(session_id):
        sess_row = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
        resolved_session_id = session_id
    if sess_row is None:
        # create session
        resolved_session_id = session_id if sess_re.match(session_id) else _new_id("nkm_sess_")
        sess_row = {
            "id": resolved_session_id,
            "current_database_id": target_db.get("id"),
            "status": "open",
            "last_activity_at": now,
            "created_at": now,
            "updated_at": now,
            "closed_at": None,
            "expires_at": None,
        }
        sessions.append(sess_row)
    else:
        if sess_row.get("status") != "open":
            # cannot reopen closed/expired per lifecycle; create a fresh session
            resolved_session_id = _new_id("nkm_sess_")
            sess_row = {
                "id": resolved_session_id,
                "current_database_id": target_db.get("id"),
                "status": "open",
                "last_activity_at": now,
                "created_at": now,
                "updated_at": now,
                "closed_at": None,
                "expires_at": None,
            }
            sessions.append(sess_row)
        else:
            # update existing open session
            for i, s in enumerate(sessions):
                if isinstance(s, dict) and s.get("id") == session_id:
                    s2 = dict(s)
                    s2["current_database_id"] = target_db.get("id")
                    s2["last_activity_at"] = now
                    s2["updated_at"] = now
                    sessions[i] = s2
                    sess_row = s2
                    break

    _save("databases.json", databases)
    _save("sessions.json", sessions)
    _log(200, "ok", resolved_session_id=resolved_session_id, resolved_database_id=target_db.get("id"))
    return {"object": "database_switch", "data": {"session": sess_row, "database": target_db}, "ts": now, "latency_ms": int((time.time() - t0) * 1000)}

def database_list(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0124000" if __import__("os").path.isdir("./environment_mix/0124000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    _B32A = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        r = uuid.uuid4().int
        out = []
        for _ in range(20):
            out.append(_B32A[r & 31])
            r >>= 5
        return prefix + "".join(out)

    def _log(status_code, status_s, note=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("nkm_req_"),
            "endpoint": "database_list",
            "status": status_s,
            "status_code": status_code,
            "session_id": None,
            "database_id": None,
            "note": note,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _parse_dt(v):
        if not isinstance(v, str) or not v:
            return None
        try:
            vv = v[:-1] + "+00:00" if v.endswith("Z") else v
            dt = datetime.datetime.fromisoformat(vv)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    # Validate inputs
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log(400, "error", "invalid status")
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, "error", "invalid limit")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log(400, "error", "invalid cursor type")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    dbs = _load("databases.json")
    if not isinstance(dbs, list):
        dbs = []

    # Filter
    rows = []
    for r in dbs:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    # Sort by updated_at desc (fallback to created_at desc)
    def _sort_key(r):
        dt = _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return dt

    rows.sort(key=_sort_key, reverse=True)

    # Cursor is the last seen database id from prior page; start after it.
    start = 0
    next_cursor = None
    if cursor:
        found = False
        for i, r in enumerate(rows):
            if r.get("id") == cursor:
                start = i + 1
                found = True
                break
        # Real cursor behavior: treat unknown cursor as empty/expired cursor -> return first page (not an error)
        if not found:
            start = 0

    page = rows[start:start + limit]
    if start + limit < len(rows) and page:
        next_cursor = page[-1].get("id")

    out = {
        "object": "list",
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": (start + limit) < len(rows),
            "next_cursor": next_cursor,
        },
        "ts": now,
        "latency_ms": int((time.time() - t0) * 1000),
    }
    _log(200, "ok")
    return out

def database_update(database_id, status, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0124000" if __import__("os").path.isdir("./environment_mix/0124000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    db_re = re.compile(r"^nkm_db_[0-9A-HJKMNP-TV-Z]{18,}$")

    _B32A = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        r = uuid.uuid4().int
        out = []
        for _ in range(20):
            out.append(_B32A[r & 31])
            r >>= 5
        return prefix + "".join(out)

    def _log(status_code, status_s, note=None, resolved_database_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("nkm_req_"),
            "endpoint": "database_update",
            "status": status_s,
            "status_code": status_code,
            "session_id": None,
            "database_id": resolved_database_id or database_id,
            "note": note,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    if not isinstance(database_id, str) or not db_re.match(database_id):
        _log(400, "error", "database_id invalid")
        return _err("VALIDATION_ERROR", "database_id is invalid")
    if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
        _log(400, "error", "status invalid", resolved_database_id=database_id)
        return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted")

    dbs = _load("databases.json")
    if not isinstance(dbs, list):
        dbs = []

    idx = None
    for i, d in enumerate(dbs):
        if isinstance(d, dict) and d.get("id") == database_id:
            idx = i
            break
    if idx is None:
        _log(404, "error", "not found", resolved_database_id=database_id)
        return _err("NOT_FOUND", "Database not found", database_id=database_id)

    row0 = dbs[idx]
    cur = row0.get("status")
    if cur == "deleted":
        _log(400, "error", "cannot modify deleted", resolved_database_id=database_id)
        return _err("VALIDATION_ERROR", "Cannot modify a deleted database", database_id=database_id)

    transitions = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
    if status != cur and status not in transitions.get(cur, set()):
        _log(409, "error", "invalid transition", resolved_database_id=database_id)
        return _err("INVALID_TRANSITION", f"Invalid transition {cur} -> {status}", from_status=cur, to_status=status)

    # Apply mutation (persist even for idempotent? We'll still touch updated_at to reflect API call; but keep timestamps consistent with constraints)
    row = dict(row0)
    if status != cur:
        row["status"] = status
        if status == "archived":
            row["archived_at"] = now
            row["deleted_at"] = None
        elif status == "active":
            row["archived_at"] = None
            row["deleted_at"] = None
        elif status == "deleted":
            row["deleted_at"] = now
            row["archived_at"] = None
    # always update updated_at on update call
    row["updated_at"] = now

    # Enforce archived_at/deleted_at constraints
    if row.get("status") == "archived" and not row.get("archived_at"):
        row["archived_at"] = now
    if row.get("status") != "archived":
        row["archived_at"] = None
    if row.get("status") == "deleted" and not row.get("deleted_at"):
        row["deleted_at"] = now
    if row.get("status") != "deleted":
        row["deleted_at"] = None

    dbs[idx] = row
    _save("databases.json", dbs)
    _log(200, "ok", resolved_database_id=database_id)
    return {"object": "database", "data": row, "ts": now, "latency_ms": int((time.time() - t0) * 1000)}

