            "endpoint": "session_update",
            "status": status_s,
            "status_code": status_code,
            "session_id": session_id,
            "database_id": database_id,
            "note": note,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    # Validate per tool schema, but allow legacy ids present in the datastore.
    if not isinstance(session_id, str):
        _log(400, "error", "session_id wrong type")
        return _err("VALIDATION_ERROR", "session_id must be a string")
    pat = r"^nkm_sess_[0-9A-HJKMNP-TV-Z]{18,}$"
    if not re.match(pat, session_id):
        sessions_probe = _load("sessions.json")
        if isinstance(sessions_probe, list) and any(isinstance(s, dict) and s.get("id") == session_id for s in sessions_probe):
            pass
        else:
            _log(400, "error", "session_id pattern mismatch")
            return _err("VALIDATION_ERROR", "session_id is invalid", session_id=session_id)

    if not isinstance(status, str) or status not in ("open", "closed", "expired"):
        _log(400, "error", "status invalid")
        return _err("VALIDATION_ERROR", "status must be one of: open, closed, expired", status=status)

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == session_id:
            idx = i
            break

    if idx is None:
        _log(404, "error", "not found")
        return _err("NOT_FOUND", "Session not found", session_id=session_id)

    row = dict(sessions[idx]) if isinstance(sessions[idx], dict) else {}

    cur = row.get("status")
    allowed = {"open": {"closed", "expired"}, "closed": set(), "expired": set()}
    if cur not in allowed:
        _log(409, "error", "unknown current status", database_id=row.get("current_database_id"))
        return _err("CONFLICT", "Session has an unknown lifecycle state", session_id=session_id, current_status=cur)

    # Idempotent if no change
    if status == cur:
        row["last_activity_at"] = now
        row["updated_at"] = now
        sessions[idx] = row
        _save("sessions.json", sessions)
        _log(200, "ok", "idempotent", database_id=row.get("current_database_id"))
        return {"session": row}

    # Enforce lifecycle transitions; per tool description, report invalid transitions as VALIDATION_ERROR
    if status not in allowed[cur]:
        _log(400, "error", "invalid transition", database_id=row.get("current_database_id"))
        return _err(
